const $ = s => document.querySelector(s);
const escapeHTML = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{notify('浏览器未允许保存，刷新后可能丢失');return false}}
let custom = read('agent-zh-custom',[]); if(!Array.isArray(custom)) custom=[];
custom=custom.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.prompt==='string'&&typeof x.description==='string'&&categories.some(([c])=>c===x.category)&&Object.hasOwn(agents,x.agent)).map(x=>({...x,custom:true,type:'我的灵感',source:null,sourceName:'本地创建'}));
const savedData=read('agent-zh-saved',[]);let saved=new Set(Array.isArray(savedData)?savedData:[]);
let state={category:'',agent:'',query:'',saved:false,sort:'pick',limit:9};

function safeSource(value) {
  try { const url = new URL(value); return ['https:', 'http:'].includes(url.protocol) && !url.username && !url.password ? url.href : null; } catch { return null; }
}
const networkCases = Array.isArray(window.AGENT_FEED?.items) ? window.AGENT_FEED.items.filter(x => x && typeof x.id === 'string' && typeof x.title === 'string' && typeof x.sourceName === 'string' && safeSource(x.source)).map(x => ({...x, network: true})) : [];
const editorialCases = () => [...initialCases, ...custom];
const allCases = () => [...editorialCases(), ...networkCases];
function matchesFilters(item) {
  const query = state.query.trim().toLowerCase();
  return (!state.category || item.category === state.category) &&
    (!state.agent || item.agent === state.agent) && (!state.saved || saved.has(item.id)) &&
    (!query || [item.title, item.originalTitle, item.description, item.category, item.agent, item.prompt].join(' ').toLowerCase().includes(query));
}
function scrollToResults() { $('#results-start').scrollIntoView({behavior: 'smooth', block: 'start'}); }
function renderResultSummary(networkCount = networkCases.filter(matchesFilters).length) {
  const editorialCount = editorialCases().filter(matchesFilters).length;
  const label = [state.saved ? '我的收藏' : '', state.category, state.agent, state.query ? '搜索“' + state.query + '”' : ''].filter(Boolean).join(' · ') || '全部内容';
  $('#results-summary').textContent = label + '：' + networkCount + ' 条网络线索 · ' + editorialCount + ' 个编辑案例与个人灵感';
}

function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function toggleSaved(id){saved.has(id)?saved.delete(id):saved.add(id);persist('agent-zh-saved',[...saved]);render();document.querySelectorAll('[data-detail-save]').forEach(button=>{if(button.dataset.id===id){button.textContent=saved.has(id)?'★ 已收藏':'☆ 收藏灵感';button.setAttribute('aria-pressed',String(saved.has(id)));}});}
function renderSidebar(){const list=allCases();$('#total-count').textContent=list.length;$('#categories').innerHTML=categories.map(([name,icon])=>`<button class="side-filter ${state.category===name?'active':''}" aria-pressed="${state.category===name}" data-category="${name}"><span class="filter-label"><span class="category-icon">${icon}</span>${name}</span><span>${list.filter(x=>x.category===name).length}</span></button>`).join('');$('#agents').innerHTML=Object.entries(agents).map(([name,icon])=>`<button class="side-filter ${state.agent===name?'active':''}" aria-pressed="${state.agent===name}" data-agent="${name}"><span class="filter-label"><span class="agent-icon">${icon}</span>${name}</span><span>${list.filter(x=>x.agent===name).length}</span></button>`).join('');$('#all-filter').classList.toggle('active',!state.category&&!state.agent&&!state.saved);}
function render(){renderSidebar();const ids=new Set(allCases().map(x=>x.id));$('#saved-count').textContent=[...saved].filter(id=>ids.has(id)).length;$('#saved-nav').classList.toggle('nav-active',state.saved);$('#explore').classList.toggle('nav-active',!state.saved);let list=editorialCases().filter(matchesFilters);if(state.sort==='new')list=[...list].reverse();$('#list-title').textContent=state.saved?'收藏的编辑案例与个人灵感':'编辑案例与个人灵感';$('#result-count').textContent=`${list.length} 个案例`;$('#sort-pick').classList.toggle('selected',state.sort==='pick');$('#sort-new').classList.toggle('selected',state.sort==='new');$('#featured').hidden=!!(state.category||state.agent||state.query||state.saved);$('#active-filters').innerHTML=[state.category&&`<button data-clear="category">${escapeHTML(state.category)} ×</button>`,state.agent&&`<button data-clear="agent">${escapeHTML(state.agent)} ×</button>`,state.query&&`<button data-clear="query">${escapeHTML(state.query)} ×</button>`].filter(Boolean).join('');$('#case-grid').innerHTML=list.slice(0,state.limit).map(x=>`<article class="case-card"><div class="card-top"><span class="agent-icon">${agents[x.agent]}</span><span>${x.agent}</span><button class="save-btn ${saved.has(x.id)?'saved':''}" data-save="${escapeHTML(x.id)}" aria-label="${saved.has(x.id)?'取消收藏':'收藏'}：${escapeHTML(x.title)}" aria-pressed="${saved.has(x.id)}">${saved.has(x.id)?'★':'☆'}</button></div><button class="card-title" data-open="${escapeHTML(x.id)}">${escapeHTML(x.title)}</button><p class="card-description">${escapeHTML(x.description)}</p><div class="card-tags"><span class="tag">${x.category}</span><span class="tag evidence">${x.type}</span></div><div class="card-bottom"><span>${x.sourceName}</span><button data-open="${escapeHTML(x.id)}">查看提示词 ↗</button></div></article>`).join('');$('#empty').hidden=list.length>0;$('#load-more').hidden=list.length<=state.limit;$('#end-note').hidden=list.length===0||list.length>state.limit;renderResultSummary();window.renderNetworkCases?.();}
function reset(){state={category:'',agent:'',query:'',saved:false,sort:'pick',limit:9};$('#search').value='';$('#feed-search').value='';$('#feed-source').value='';render()}
function openDetail(id){const x=allCases().find(x=>x.id===id);if(!x)return;if(x.network){window.openNetworkDetail?.(id);return;}$('#detail-content').innerHTML=`<span class="modal-eyebrow">${x.agent} · ${x.category}</span><h2>${escapeHTML(x.title)}</h2><div class="detail-tags"><span class="tag">${x.type}</span><span class="tag evidence">${x.sourceName}</span></div><p>${escapeHTML(x.detail||x.description)}</p><h3>开始前，值得知道</h3><p>${escapeHTML(x.limit||'这是一个可尝试的工作流模板。请结合所用工具的文件访问、联网能力与实际权限调整，检查输出后再用于正式工作。')}</p><h3>你的中文起步提示词</h3><div class="prompt-box" id="prompt-text">${escapeHTML(x.prompt)}</div><div class="detail-actions"><button class="primary" id="copy-prompt">复制提示词 ⧉</button><button class="secondary" id="detail-save" data-detail-save aria-pressed="${saved.has(id)}" data-id="${escapeHTML(x.id)}">${saved.has(id)?'★ 已收藏':'☆ 收藏灵感'}</button>${x.custom?'<button class="secondary" id="delete-idea">删除</button>':''}</div>${x.source?`<a class="source-link" href="${escapeHTML(x.source)}" target="_blank" rel="noopener">阅读原始来源 ↗</a>`:''}<p class="detail-notice">中文提示词为本站编写的尝试模板，不是原作者的逐字提示词。请替换方括号中的内容后使用。</p>`;$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(x.prompt);$('#copy-prompt').textContent='已复制 ✓'}catch{const selection=window.getSelection();const range=document.createRange();range.selectNodeContents($('#prompt-text'));selection.removeAllRanges();selection.addRange(range);$('#copy-prompt').textContent='请按 Ctrl+C 复制所选文字'}};$('#detail-save').onclick=()=>toggleSaved(id);if(x.custom)$('#delete-idea').onclick=()=>{custom=custom.filter(c=>c.id!==id);saved.delete(id);persist('agent-zh-custom',custom);persist('agent-zh-saved',[...saved]);$('#detail').close();render();notify('已删除这条灵感')};$('#detail').showModal()}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.open)openDetail(button.dataset.open);if(button.dataset.save)toggleSaved(button.dataset.save);if(button.hasAttribute('data-category')){state.category=state.category===button.dataset.category?'':button.dataset.category;state.limit=9;render();scrollToResults()}if(button.hasAttribute('data-agent')){state.agent=state.agent===button.dataset.agent?'':button.dataset.agent;state.limit=9;render();scrollToResults()}if(button.dataset.query){state.query=button.dataset.query;$('#search').value=state.query;state.limit=9;render();scrollToResults()}if(button.dataset.clear){state[button.dataset.clear]='';$('#search').value=state.query;render()}if(button.classList.contains('close'))button.closest('dialog').close()});
$('#search').addEventListener('input',e=>{state.query=e.target.value;state.limit=9;render()});
$('#load-more').onclick=()=>{state.limit+=9;render()};$('#sort-pick').onclick=()=>{state.sort='pick';render()};$('#sort-new').onclick=()=>{state.sort='new';render()};$('#explore').onclick=()=>{reset();scrollToResults()};$('.brand').onclick=e=>{e.preventDefault();reset();window.scrollTo({top:0,behavior:'smooth'})};$('#all-filter').onclick=()=>{reset();scrollToResults()};$('#reset').onclick=reset;$('#saved-nav').onclick=()=>{reset();state.saved=true;render();scrollToResults()};$('#about').onclick=()=>$('#about-dialog').showModal();$('#random').onclick=()=>openDetail(allCases()[Math.floor(Math.random()*allCases().length)].id);$('#back-top').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});
const setTheme=dark=>{document.body.classList.toggle('dark',dark);$('#theme').setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式');$('#theme').textContent=dark?'☀':'◐'};setTheme(read('agent-zh-dark',false));$('#theme').onclick=()=>{const dark=!document.body.classList.contains('dark');setTheme(dark);persist('agent-zh-dark',dark)};
$('#form-category').innerHTML=categories.map(([c])=>`<option>${c}</option>`).join('');$('#form-agent').innerHTML=Object.keys(agents).map(a=>`<option>${a}</option>`).join('');const showSubmit=()=>$('#submit-dialog').showModal();$('#submit').onclick=showSubmit;$('#submit-bottom').onclick=showSubmit;
$('#idea-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);const title=String(form.get('title')).trim(),description=String(form.get('description')).trim(),prompt=String(form.get('prompt')).trim();if(!title||!description||!prompt){notify('请填写标题、说明和提示词');return}const idea={id:'local-'+crypto.randomUUID(),title,description,prompt,agent:form.get('agent'),category:form.get('category'),type:'我的灵感',sourceName:'本地创建',custom:true};custom.push(idea);const stored=persist('agent-zh-custom',custom);e.target.reset();$('#submit-dialog').close();reset();state.sort='new';render();$('#directory').scrollIntoView({behavior:'smooth'});notify(stored?'灵感已保存到当前浏览器':'灵感已添加，但当前浏览器无法持久保存')};
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()}));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});render();
